#ifndef PRACTICA_CONTROL_AJUSTE_H
#define PRACTICA_CONTROL_AJUSTE_H

// Accepte valor, inferior et superior dans [-20,20], avec inferior <= superior.
// Ajouter ajuste à valor le place dans l'intervalle avec le changement d'amplitude minimale :
// zéro à l'intérieur, jusqu'à inferior en dessous et jusqu'à superior au-dessus.
// Renvoie true et écrit cet ajustement si la demande est acceptée.
// Renvoie false et conserve exactement ajuste si la demande est rejetée.
// N'affiche rien et ne termine pas le programme.
bool intentar_ajuste(int valor, int inferior, int superior, int& ajuste);

#endif

#include "control/ajuste.h"

bool intentar_ajuste(int valor, int inferior, int superior, int& ajuste) {
    if (valor < -20 || valor > 20 || inferior < -20 || inferior > 20
            || superior < -20 || superior > 20 || inferior > superior) {
        return false;
    }
    if (valor < inferior) {
        ajuste = inferior - valor;
    } else if (valor > superior) {
        ajuste = superior - valor;
    } else {
        ajuste = 0;
    }
    return true;
}

#include "control/ajuste.h"
#include <iostream>

void informar_rechazo(std::ostream& destino, int peticion,
                     int valor, int inferior, int superior) {
    destino << "Rejet : demande=" << peticion << " valeur=" << valor
            << " inférieur=" << inferior << " supérieur=" << superior
            << ". Les valeurs de -20 à 20 sont autorisées avec inferior <= superior."
            << " Vérifiez les trois valeurs.\n";
}

int main() {
    int valor{0};
    int inferior{0};
    int superior{0};
    int ajuste{77};
    int peticion{0};
    int aceptadas{0};
    int rechazadas{0};
    int suma{0};
    while (std::cin >> valor >> inferior >> superior) {
        ++peticion;
        if (intentar_ajuste(valor, inferior, superior, ajuste)) {
            ++aceptadas;
            suma += ajuste;
            std::cout << "Demande=" << peticion << " Ajustement=" << ajuste << "\n";
        } else {
            ++rechazadas;
            informar_rechazo(std::cerr, peticion, valor, inferior, superior);
        }
    }
    std::cout << "Acceptées=" << aceptadas << " Rejetées=" << rechazadas
              << " Somme=" << suma << "\n";
    return rechazadas > 0 ? 1 : 0;
}

#include "control/ajuste.h"
#include <iostream>

bool comprobar(int caso, int valor, int inferior, int superior,
               int inicial, bool aceptacion_esperada, int ajuste_esperado) {
    int obtenido{inicial};
    const bool aceptado = intentar_ajuste(valor, inferior, superior, obtenido);
    const bool coincide = aceptado == aceptacion_esperada && obtenido == ajuste_esperado;
    std::cout << "Cas=" << caso << " Accepte=" << aceptado << " Ajustement=" << obtenido
              << " AcceptationAttendue=" << aceptacion_esperada
              << " AjustementAttendu=" << ajuste_esperado;
    if (coincide) { std::cout << " OK\n"; }
    else { std::cout << " ÉCHEC\n"; }
    return coincide;
}

int main() {
    int fallos{0};
    if (!comprobar(1, 2, 3, 7, 77, true, 1)) { ++fallos; }
    if (!comprobar(2, 5, 3, 7, -8, true, 0)) { ++fallos; }
    if (!comprobar(3, 9, 3, 7, 19, true, -2)) { ++fallos; }
    if (!comprobar(4, 4, 4, 4, -4, true, 0)) { ++fallos; }
    if (!comprobar(5, -20, 20, 20, 8, true, 40)) { ++fallos; }
    if (!comprobar(6, 20, -20, -20, 17, true, -40)) { ++fallos; }
    if (!comprobar(7, 0, 7, 3, 77, false, 77)) { ++fallos; }
    if (!comprobar(8, 21, 3, 7, -8, false, -8)) { ++fallos; }
    if (!comprobar(9, -21, 3, 7, 19, false, 19)) { ++fallos; }
    if (!comprobar(10, 0, -21, 7, -4, false, -4)) { ++fallos; }
    if (!comprobar(11, 0, 3, 21, 8, false, 8)) { ++fallos; }
    std::cout << "Échecs=" << fallos << "\n";
    return fallos == 0 ? 0 : 1;
}

bool intentar_ajuste(int valor, int inferior, int superior, int& ajuste) {
    if (valor < -20 || valor > 20 || inferior < -20 || inferior > 20
            || superior < -20 || superior > 20 || inferior > superior) {
        return false;
    }
    if (valor < inferior) {
        ajuste = inferior - valor;
    } else if (valor > superior) {
        ajuste = valor - superior;
    } else {
        ajuste = 0;
    }
    return true;
}
